<template><div class="page"><SiteNav/><main><section class="contact-hero"><div class="shell"><p class="eyebrow">Available for the right work</p><h1 class="page-title">Let’s make the next release <em>more reliable.</em></h1><p class="intro">Open to Junior Web Developer and Junior Full-Stack Developer roles, plus web, mobile, QA testing, documentation, and technical-support opportunities.</p></div></section><section class="contact-section"><div class="shell contact-grid"><aside><p class="eyebrow">Direct details</p><h2>Start with a straightforward conversation.</h2><p>Tell me what you are building, what needs improving, or what needs a rigorous test pass. I’ll respond with the clearest next step I can offer.</p><dl><div><dt>Email</dt><dd><a href="mailto:aaronryogemang@gmail.com">aaronryogemang@gmail.com</a></dd></div><div><dt>Location</dt><dd>Ozamiz City, Misamis Occidental, Philippines</dd></div><div><dt>GitHub</dt><dd><a href="https://github.com/Admiral23kizaru" target="_blank" rel="noopener">github.com/Admiral23kizaru ↗</a></dd></div></dl><p class="privacy-note">For privacy and to avoid spam, I don’t publish a phone number. Please use email or this form.</p></aside><form @submit.prevent="sendEmail"><p class="form-label">Send a message</p><label>Name<input v-model="name" required placeholder="Your name"/></label><label>Email<input v-model="email" required type="email" placeholder="you@example.com"/></label><label>What do you need?<select v-model="subject"><option>Junior developer role</option><option>Web development</option><option>Mobile application development</option><option>QA testing</option><option>Documentation</option><option>Technical support</option><option>Other</option></select></label><label>Message<textarea v-model="message" required rows="6" placeholder="A short description of the opportunity or work."></textarea></label><button class="button primary" type="submit">Prepare email ↗</button><p v-if="sent" class="form-note">Your email client should now have a message addressed to Aaron.</p></form></div></section></main><SiteFooter/></div></template>
<script setup>import{ref}from'vue';import SiteNav from'../components/SiteNav.vue';import SiteFooter from'../components/SiteFooter.vue';const name=ref('');const email=ref('');const subject=ref('Junior developer role');const message=ref('');const sent=ref(false);function sendEmail(){const body=`Name: ${name.value}\nEmail: ${email.value}\n\n${message.value}`;window.location.href=`mailto:aaronryogemang@gmail.com?subject=${encodeURIComponent(subject.value)}&body=${encodeURIComponent(body)}`;sent.value=true}</script>
<style scoped>.contact-hero{padding:104px 0 80px;border-bottom:1px solid var(--line);background:radial-gradient(circle at 14% 20%,rgba(184,255,75,.09),transparent 23rem)}.contact-section{padding:76px 0 110px}.contact-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:88px}.contact-grid h2{font-size:clamp(2.3rem,4.4vw,4.7rem);line-height:.96;letter-spacing:-.075em;margin:20px 0}.contact-grid>aside>p:not(.eyebrow){color:var(--muted)}dl{margin:37px 0 26px;border-top:1px solid var(--line)}dl div{padding:14px 0;border-bottom:1px solid var(--line)}dt{font:.62rem var(--mono);letter-spacing:.1em;text-transform:uppercase;color:var(--cyan)}dd{margin:4px 0 0;font-size:.84rem;color:#dce4ee}dd a:hover{color:var(--lime)}.privacy-note{border-left:2px solid var(--lime);padding:10px 0 10px 14px!important;font-size:.77rem!important;line-height:1.55;color:#cbd6e3!important}form{display:grid;gap:18px;padding:29px;border:1px solid var(--line);background:linear-gradient(135deg,rgba(18,25,38,.82),rgba(13,17,24,.66))}.form-label{font-size:1.5rem;font-weight:800;letter-spacing:-.04em;margin:0 0 2px}label{font-size:.73rem;font-weight:800;color:#dce4ee}input,select,textarea{display:block;width:100%;margin-top:7px;padding:13px;border:1px solid var(--line);background:#090d13;color:var(--text);font:400 .9rem var(--font);border-radius:0}input:focus,select:focus,textarea:focus{outline:none;border-color:var(--cyan);box-shadow:0 0 0 2px rgba(82,231,255,.09)}.form-note{color:var(--lime);font-size:.78rem;margin:0}@media(max-width:760px){.contact-hero{padding:76px 0 65px}.contact-grid{grid-template-columns:1fr;gap:48px}}</style>
